    "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    xmlns:tools=\"http://schemas.android.com/tools\"\n    package=\"com.novaforge.launcher\">\n\n    <!-- Essential Launcher & Hardware Permissions -->\n    <uses-permission android:name=\"android.permission.QUERY_ALL_PACKAGES\" \n        tools:ignore=\"QueryAllPackagesPermission\" />\n    <uses-permission android:name=\"android.permission.REQUEST_DELETE_PACKAGES\" />\n    <uses-permission android:name=\"android.permission.VIBRATE\" />\n    <uses-permission android:name=\"android.permission.SET_WALLPAPER\" />\n    <uses-permission android:name=\"android.permission.INTERNET\" />\n    <uses-permission android:name=\"android.permission.ACCESS_NETWORK_STATE\" />\n    <uses-permission android:name=\"android.permission.READ_CALENDAR\" />\n\n    <!-- Query all launchable activities for the App Drawer -->\n    <queries>\n        <intent>\n            <action android:name=\"android.intent.action.MAIN\" />\n            <category android:name=\"android.intent.category.LAUNCHER\" />\n        </intent>\n    </queries>\n\n    <application\n        android:name=\".NovaForgeApp\"\n        android:allowBackup=\"true\"\n        android:icon=\"@mipmap/ic_launcher\"\n        android:label=\"@string/app_name\"\n        android:roundIcon=\"@mipmap/ic_launcher_round\"\n        android:supportsRtl=\"true\"\n        android:theme=\"@style/Theme.NovaForge\">\n\n        <!-- Main Launcher Home Activity -->\n        <activity\n            android:name=\".MainActivity\"\n            android:exported=\"true\"\n            android:launchMode=\"singleTask\"\n            android:clearTaskOnReset=\"true\"\n            android:stateNotNeeded=\"true\"\n            android:resumeWhilePausing=\"true\"\n            android:windowSoftInputMode=\"adjustPan\">\n            \n            <!-- Standard Android Launcher Intent Filters -->\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.HOME\" />\n                <category android:name=\"android.intent.category.DEFAULT\" />\n            </intent-filter>\n\n            <!-- Launchable from app list during development -->\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n            </intent-filter>\n        </activity>\n\n        <!-- Dynamic app installation and removal detection -->\n        <receiver\n            android:name=\".receiver.PackageChangeReceiver\"\n            android:exported=\"true\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.PACKAGE_ADDED\" />\n                <action android:name=\"android.intent.action.PACKAGE_REMOVED\" />\n                <action android:name=\"android.intent.action.PACKAGE_REPLACED\" />\n                <data android:scheme=\"package\" />\n            </intent-filter>\n        </receiver>\n\n        <!-- Notification listener for MediaSession playback controls -->\n        <service\n            android:name=\".service.NovaForgeNotificationListener\"\n            android:exported=\"true\"\n            android:label=\"NovaForge Media Controls\"\n            android:permission=\"android.permission.BIND_NOTIFICATION_LISTENER_SERVICE\">\n            <intent-filter>\n                <action android:name=\"android.service.notification.NotificationListenerService\" />\n            </intent-filter>\n        </service>\n\n    </application>\n\n</manifest>\n"
