    "path": "app/src/main/java/com/novaforge/launcher/receiver/PackageChangeReceiver.kt",
    "category": "kotlin",
    "description": "Android source file: app/src/main/java/com/novaforge/launcher/receiver/PackageChangeReceiver.kt",
    "isBinary": false,
    "content": "package com.novaforge.launcher.receiver\n\nimport android.content.BroadcastReceiver\nimport android.content.Context\nimport android.content.Intent\nimport com.novaforge.launcher.NovaForgeApp\n\nclass PackageChangeReceiver : BroadcastReceiver() {\n    override fun onReceive(context: Context, intent: Intent?) {\n        val app = context.applicationContext as? NovaForgeApp ?: return\n        when (intent?.action) {\n            Intent.ACTION_PACKAGE_ADDED,\n            Intent.ACTION_PACKAGE_REMOVED,\n            Intent.ACTION_PACKAGE_REPLACED -> {\n                app.appRepository.reloadInstalledApps()\n            }\n        }\n    }\n}\n"
