    "content": "package com.novaforge.launcher.service\n\nimport android.service.notification.NotificationListenerService\n\n/**\n * Required by Android to access MediaSessionManager.getActiveSessions.\n */\nclass NovaForgeNotificationListener : NotificationListenerService()\n"
